mapper.sql:
WHERE 1 = 1

    AND t.status = #{status}


    AND t.course_id = #{courseId}


    AND (t.primary_teacher_id = #{teacherId} OR t.assistant_teacher_id = #{teacherId})


    AND c.course_type = #{courseType}


    AND t.task_batch = #{taskBatch}


    AND (
        c.name LIKE CONCAT('%', #{keyword}, '%')
        OR c.code LIKE CONCAT('%', #{keyword}, '%')
        OR pt.name LIKE CONCAT('%', #{keyword}, '%')
        OR at.name LIKE CONCAT('%', #{keyword}, '%')
        OR t.id IN (
            SELECT ttcg.teaching_task_id
            FROM teaching_task_class_group ttcg
            JOIN class_group cg ON cg.id = ttcg.class_group_id
            WHERE cg.name LIKE CONCAT('%', #{keyword}, '%')
        )
    )
